<script setup lang="ts">
import {onMounted,watch} from 'vue';
import {t,formatDate} from '@kuaixie/i18n';
import {usePaymentRefunds,paymentRefundStateKey,paymentRefundEventKey} from '@kuaixie/ui/usePaymentRefunds';
import {api} from '../api/client';
import {uniEventValue} from '../utils/uniEvent';
const props=defineProps<{refundId?:string}>();
const p=usePaymentRefunds(api,async(title,content)=>!!(await uni.showModal({title,content})).confirm);
watch(()=>props.refundId,id=>{if(id)void p.loadDetail(id)},{immediate:true});
onMounted(()=>{void p.loadList();void p.loadEligible()});
</script>
<template><view class="payment-refunds"><view class="op-title">{{t('refund.title')}}</view><view class="v15-notice">{{t('refund.boundary')}}</view><view class="v15-notice">{{t('refund.reserveNotice')}}</view><view class="v15-notice">{{t('refund.onceNotice')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><view v-if="p.notice.value" class="op-muted">{{p.notice.value}}</view><view v-if="p.loading.value" class="op-empty">{{t('account.loading')}}</view><button :disabled="p.busy.value||p.confirming.value||p.loading.value" @click="p.loadList();p.loadEligible()">{{t('refund.reload')}}</button>
<view class="op-card"><view class="op-card-title">{{t('refund.apply')}}</view><picker :disabled="p.locked.value" :range="p.eligible.value.map(row=>row.merchantName+' · '+row.baseAmount+' CNY · '+row.id)" @change="p.paymentId.value=p.eligible.value[Number(uniEventValue($event))]?.id||''"><view class="v15-selector">{{p.selected.value?p.selected.value.merchantName+' · '+p.selected.value.paymentAmount+' '+p.selected.value.paymentCurrency:t('refund.payment')}} ⌄</view></picker><view v-if="!p.eligible.value.length&&!p.loading.value" class="op-muted">{{t('refund.noEligible')}}</view><view v-if="p.selected.value">{{t('refund.fullAmount')}}: {{p.selected.value.paymentAmount}} {{p.selected.value.paymentCurrency}}</view><text>{{t('refund.reason')}}</text><textarea v-model="p.reason.value" :disabled="p.locked.value" maxlength="200" class="v15-area"/><button :disabled="p.busy.value||p.confirming.value||!!p.uncertain.value" @click="p.apply()">{{t(p.pending.value?'refund.retryOriginal':'refund.apply')}}</button></view>
<view v-if="p.pending.value" class="v15-notice">{{t('refund.pending')}}</view><view v-if="p.uncertain.value" class="v15-notice">{{t('refund.uncertainAction')}}</view><view v-if="!p.rows.value.length&&!p.loading.value" class="op-empty">{{t('refund.empty')}}</view><view v-for="row in p.rows.value" :key="row.id" class="op-card"><button :disabled="p.locked.value||p.loading.value" @click="p.loadDetail(row.id)">{{row.paymentId}} · {{t(paymentRefundStateKey(row.status))}}</button><view>{{row.paymentAmount}} {{row.paymentCurrency}} · {{formatDate(row.createdAt)}}</view></view><button v-if="p.more.value" :disabled="p.loading.value" @click="p.loadList(true)">{{t('account.more')}}</button>
<view v-if="p.entry.value" class="op-card"><view class="op-card-title">{{t(paymentRefundStateKey(p.entry.value.status))}}</view><view class="op-row"><text>{{t('refund.id')}}</text><text selectable>{{p.entry.value.id}}</text></view><view class="op-row"><text>{{t('refund.payment')}}</text><text selectable>{{p.entry.value.paymentId}}</text></view><view class="op-row"><text>{{t('refund.fullAmount')}}</text><text>{{p.entry.value.paymentAmount}} {{p.entry.value.paymentCurrency}}</text></view><view class="op-row"><text>{{t('refund.walletReserve')}}</text><text>{{p.entry.value.baseAmount}} {{p.entry.value.baseCurrency}}</text></view><text>{{t('refund.reason')}}</text><view class="v14-body">{{p.entry.value.reason}}</view><text>{{t('refund.reviewReason')}}</text><view class="v14-body">{{p.entry.value.reviewNote||'—'}}</view><view class="op-row"><text>{{t('refund.providerReference')}}</text><text selectable>{{p.entry.value.providerRefundId||'—'}}</text></view><view class="op-muted">{{t('refund.updated')}}: {{formatDate(p.entry.value.updatedAt)}}</view><view v-if="p.entry.value.lastError" class="v15-notice">{{t('refund.providerIssue')}}</view><view v-if="p.entry.value.status==='succeeded'" class="v15-notice">{{t('refund.successRecorded')}}</view><button :disabled="p.busy.value||p.confirming.value||p.loading.value||!!p.pending.value" @click="p.loadDetail(p.entry.value.id)">{{t('refund.readCurrent')}}</button><button v-if="p.canRefresh.value" :disabled="p.busy.value" @click="p.refresh()">{{t('refund.queryProvider')}}</button><button v-if="p.canCancel.value" @click="p.cancel()">{{t('refund.cancel')}}</button><view class="op-card-title">{{t('refund.timeline')}}</view><view v-if="p.eventsLoading.value" class="op-muted">{{t('account.loading')}}</view><view v-for="event in p.events.value" :key="event.id" class="op-card"><view>{{t(paymentRefundEventKey(event.action))}}</view><text class="op-muted">{{formatDate(event.createdAt)}}</text></view><button v-if="p.moreEvents.value" :disabled="p.eventsLoading.value" @click="p.loadEvents(p.entry.value.id,true)">{{t('account.more')}}</button></view></view></template>
<style scoped>.payment-refunds{padding:16px}.payment-refunds button{margin:10px 0}.payment-refunds text{display:block;margin:10px 0}.payment-refunds textarea{width:100%;box-sizing:border-box}.payment-refunds .op-row{gap:12px}.payment-refunds .op-row text:last-child{overflow-wrap:anywhere;text-align:right;max-width:65%}</style>
